  test("a phase shift changes the linear flow but not the optimised dispatch") {
    assume(available, "goldens missing")
    // The half of the claim that was missing. `LinearPowerFlowSuite` asserted
    // "PyPSA's LOPF ignores the shift" by comparing two goldens to each other,
    // which invokes no port code at all -- so if someone added a shift term to
    // `Cycles`, every test would still pass while this module silently diverged
    // from the golden it is supposed to match.
    //
    // PyPSA's Kirchhoff row is `sum(x_l s_l) == 0` with no shift term, so the
    // optimised flows on `phase-shift` are identical to `transformer-levels`,
    // which differs from it only by 30 degrees on t1. The linear flow is not: t1
    // carries -840.53 MW there against +150.66 here.
    val expected = results("phase-shift")("optimize")
    assert(!expected.obj.contains("error"), s"golden solve failed: ${expected.obj.get("error")}")

    val n      = network("phase-shift")
    val result = Lopf.solve(n, params)
    assertEquals(result.status, SolveStatus.Optimal, s"${result.solution}")

    val target = expected("objective").num
    assertEqualsDouble(result.objective, target, 1e-6 * target, s"against PyPSA's $target")

    val flows = expected("transformer_p0")
    n.snapshots.indices.foreach { t =>
      n.require("Transformer").ids.foreach { id =>
        assertEqualsDouble(result.dispatch("Transformer", id, t), frameValue(flows, t, id), 1e-3,
          s"snapshot $t, transformer $id")
      }
    }

    // The fixture really does carry a shift, so this is not passing because the
    // two networks are the same.
    assert(
      n.require("Transformer").float("phase_shift", "t1") != 0.0,
      "the fixture no longer has a phase shift, so it cannot distinguish anything",
    )
    // And the unshifted sibling optimises to the same flows, which is the
    // property being pinned.
    val plain = Lopf.solve(network("transformer-levels"), params)
    n.snapshots.indices.foreach { t =>
      assertEqualsDouble(
        result.dispatch("Transformer", "t1", t),
        plain.dispatch("Transformer", "t1", t),
        1e-3,
        s"the optimised flows differ under a shift at snapshot $t",
      )
    }
  }

  test("an inactive component is excluded from the model, not dispatched at zero") {
    assume(available, "goldens missing")
    // `active` was read nowhere in this port, so an inactive component was built
    // into the model like any other. PyPSA removes it -- found by enumerating the
    // attributes the schema declares and subtracting those the source ever names,
    // which is the only technique that finds this shape: an attribute nothing
    // reads has no call site to refuse at and nothing to sabotage in a test.
    //
    // Compared against `inactive-removed`, which is the same network with the
    // line genuinely deleted, and *not* against `inactive`'s own `optimize`
    // block. The two disagree inside PyPSA: `cycle_matrix` keeps the inactive
    // branch's loop while the Kirchhoff builder drops its flow term, so the row
    // collapses to a voltage law for a loop that is not closed and pins hv31 to
    // 27.6 MW on a branch rated 1700. That costs 68,407.58 against the 19,800 a
    // deleted line gives. PyPSA's own linear flow excludes inactive branches from
    // topology properly, so its two L2 models disagree about the same network;
    // this port follows the linear flow. The golden says so in a `not_a_target`
    // note beside the numbers.
    val correct = results("inactive-removed")("optimize")
    val pypsas  = results("inactive")("optimize")
    assert(pypsas.obj.contains("not_a_target"), "the golden no longer warns that it is not a target")

    val n      = network("inactive")
    val result = Lopf.solve(n, params)
    assertEquals(result.status, SolveStatus.Optimal, s"${result.solution}")

    val target = correct("objective").num
    assertEqualsDouble(result.objective, target, 1e-6 * target, s"against the deleted-line answer $target")

    // The two PyPSA answers really do differ, so this is not passing because the
    // distinction is moot.
    assert(
      math.abs(pypsas("objective").num - target) > 1.0,
      "PyPSA's two answers now agree, so the inconsistency this pins is gone",
    )

    // Flows, not just the objective. Both networks cost 19,800 -- the cheap
    // generator serves everything either way and no rating binds -- so the
    // objective cannot tell them apart, and asserting only that would pass
    // against an implementation that ignored `active` entirely. What changes is
    // where the power goes: hv31 carries the whole 300 MW to hv3 instead of
    // sharing it with hv23, 197.2 -> 46.7 on hv12.
    val flows = correct("line_p0")
    val whole = Lopf.solve(network("standard-types"), params)
    // Only the lines the deleted-line golden has -- it does not carry an `hv23`
    // column at all, because there is no such line in that network. The inactive
    // one is checked separately below.
    val compared = flows("columns").arr.map(_.str).toSet
    assert(compared.nonEmpty && !compared.contains("hv23"), s"unexpected golden columns: $compared")
    n.snapshots.indices.foreach { t =>
      n.require("Line").ids.filter(compared.contains).foreach { id =>
        assertEqualsDouble(result.dispatch("Line", id, t), frameValue(flows, t, id), 1e-3,
          s"snapshot $t, line $id")
      }
    }
    assert(
      math.abs(result.dispatch("Line", "hv31", 0) - whole.dispatch("Line", "hv31", 0)) > 100.0,
      "the flag changes no flow, so this test cannot discriminate",
    )
    assertEqualsDouble(result.dispatch("Line", "hv23", 0), 0.0, 1e-9, "the inactive line carries power")
  }

  test("ramp-limited dispatch matches PyPSA's") {
    assume(available, "goldens missing")
    // Ramp limits were the third defect the schema-minus-source sweep turned up:
    // `ramp_limit_up` and `ramp_limit_down` were named in this module only inside
    // `UnitCommitment`'s refusal, so a plain LOPF solved the unconstrained
    // problem and reported `Optimal`. No pre-existing golden could see it --
    // none of them sets a ramp limit at all.
    val expected = results("ramp-limits")("optimize")
    assert(!expected.obj.contains("error"), s"golden solve failed: ${expected.obj.get("error")}")

    val n      = network("ramp-limits")
    val result = Lopf.solve(n, params)
    assertEquals(result.status, SolveStatus.Optimal, s"${result.solution}")

    val target = expected("objective").num
    assertEqualsDouble(result.objective, target, 1e-6 * target, s"against PyPSA's $target")

    // Generators and the link both, because ramp limits are not a generator
    // attribute -- PyPSA ramps Generator, Link and Process alike, and an
    // implementation that swept only generators would match the objective here
    // only by accident.
    val generators = expected("generator_p")
    val links      = expected("link_p0")
    n.snapshots.indices.foreach { t =>
      n.require("Generator").ids.foreach { id =>
        assertEqualsDouble(result.dispatch("Generator", id, t), frameValue(generators, t, id), 1e-4,
          s"generator $id at snapshot $t")
      }
      n.require("Link").ids.foreach { id =>
        assertEqualsDouble(result.dispatch("Link", id, t), frameValue(links, t, id), 1e-4,
          s"link $id at snapshot $t")
      }
    }

    // The extendable unit's limits ride on its capacity variable rather than on
    // a number in the file, so the capacity has to come out right for the ramp
    // rows to mean anything.
    assertEqualsDouble(result.capacity("Generator", "new"),
      expected("nominal_opt")("Generator")("new").num, 1e-4, "the extendable unit's capacity")
  }

  test("each ramp path in the fixture binds, rather than merely being set") {
    assume(available, "goldens missing")
    // Guarding the guard, as for `storage-cycle` and `store-bank`. A limit that
    // is set but never tight tests nothing: the comparison above would pass
    // against an implementation that dropped the rows. Each number here is a
    // constraint sitting exactly on its bound at the golden optimum.
    val expected = results("ramp-limits")("optimize")
    val p        = expected("generator_p")
    val flow     = expected("link_p0")

    // `base`: the first snapshot is bounded against `p_init`, not against a
    // previous dispatch that does not exist. 60 + 0.2 * 300.
    assertEqualsDouble(frameValue(p, 0, "base"), 120.0, 1e-6, "p_init does not bind at the first snapshot")

    // `cold`: `up_time_before = 0` makes PyPSA read `p_init` as 0 *and* scale the
    // up row by a prior status of zero, which pins the first snapshot to zero.
    // This is the one attribute here that changes whether a row exists at all.
    assertEqualsDouble(frameValue(p, 0, "cold"), 0.0, 1e-6, "up_time_before does not hold the unit down")

    // `flex`: the time-varying limit. Its down limit of 0.5 * 150 is hit exactly
    // between the first two snapshots, and a `static.contains` reader would see
    // no limit at all -- both are `static or series` in PyPSA.
    assertEqualsDouble(frameValue(p, 0, "flex") - frameValue(p, 1, "flex"), 75.0, 1e-6,
      "the series ramp limit is not tight anywhere")

    // `new`: extendable, so its band is 0.3 times a capacity *variable*.
    val built = expected("nominal_opt")("Generator")("new").num
    assertEqualsDouble(built, 200.0, 1e-6, "the extendable unit was not built")
    assertEqualsDouble(frameValue(p, 3, "new") - frameValue(p, 2, "new"), 0.3 * built, 1e-6,
      "the extendable unit's ramp band is not tight")

    // `tie`: a Link, stepping exactly 0.25 * 200.
    assertEqualsDouble(frameValue(flow, 3, "tie") - frameValue(flow, 2, "tie"), 50.0, 1e-6,
      "the link's ramp limit is not tight")
  }

  test("dropping the ramp columns makes this port cheaper, as it silently was") {
    assume(available, "goldens missing")
    // The discriminating half. The comparison above would also pass if the rows
    // were built but vacuous, so this asserts the sign of the error the bug
    // actually had: a dropped restriction is indistinguishable from an absent one
    // to an inequality, and the answer comes out *below* the truth.
    val limited = Lopf.solve(network("ramp-limits"), params).objective
    val free = Lopf.solve(
      mutate("ramp-limits", "generators.csv", text =>
        setColumn(setColumn(text, "ramp_limit_up", "nan"), "ramp_limit_down", "nan")),
      params,
